const UserCard = React.memo(function UserCard({ user }) {
  console.log('Rendered:', user.name);
  return (
    <div className="card">
      <h3>{user.name}</h3>
      <p>{user.email}</p>
    </div>
  );
});

// Parent re-renders, but UserCard only re-renders
// when the user prop object reference changes.

function SearchResults({ items, query }) {
  const filteredItems = useMemo(() => {
    console.log('Filtering...');
    return items.filter((item) =>
      item.name.toLowerCase().includes(query.toLowerCase())
    );
  }, [items, query]);

  return (
    <ul>
      {filteredItems.map((item) => (
        <li key={item.id}>{item.name}</li>
      ))}
    </ul>
  );
}

function Parent() {
  const [count, setCount] = useState(0);

  const handleRemove = useCallback((id) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  }, []);

  return (
    <div>
      <button onClick={() => setCount((c) => c + 1)}>
        Re-render parent ({count})
      </button>
      <ItemList items={items} onRemove={handleRemove} />
    </div>
  );
}

const ItemList = React.memo(({ items, onRemove }) => {
  return items.map((item) => (
    <Item key={item.id} item={item} onRemove={onRemove} />
  ));
});
